/**
 * A pele do tubarão — as ranhuras que domam a água.
 *
 * A pele não é lisa: é coberta de sulcos finíssimos, alinhados com o movimento.
 * No espaçamento certo eles prendem os redemoinhos miúdos junto à superfície e o
 * fluxo passa por cima liso. Largos demais ou apertados demais, a turbulência
 * volta — e é isso que a cena mostra, porque um número de "turbulência: 47%" não
 * diz nada ao olho.
 *
 * As linhas de corrente são desenhadas com uma ondulação proporcional à
 * turbulência medida pelo renderizador: fluxo calmo vira reta.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const PELE = '#6f7f92';
const PELE_CLARA = '#8b9cae';

const fluxo: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const espacamento = limitar(numeroDe(valores, 'e', 50), 1, 100);
    const turbulencia = limitar(numeroDe(info, 'turb', 50), 0, 100);
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : cor.azul;

    titulo(ctx, L, A, 'Sulcos na medida, água que escorre');

    const x0 = L * 0.05;
    const x1 = L * 0.95;
    const yPele = A * 0.68;

    // ── A água por cima, em linhas de corrente ────────────────────────────
    const desordem = turbulencia / 100;
    const linhas = 6;

    for (let n = 0; n < linhas; n++) {
      const base = A * 0.22 + n * ((yPele - A * 0.24) / linhas);
      // Quanto mais perto da pele, mais a linha sente a superfície.
      const proximidade = (n + 1) / linhas;
      const amplitude = desordem * A * 0.035 * proximidade;

      ctx.strokeStyle = n === linhas - 1 ? tinta : cor.azulClaro;
      ctx.lineWidth = n === linhas - 1 ? 2.4 : 1.6;
      ctx.globalAlpha = 0.45 + proximidade * 0.55;
      ctx.lineJoin = 'round';
      ctx.beginPath();
      for (let i = 0; i <= 120; i++) {
        const u = i / 120;
        const px = x0 + u * (x1 - x0);
        const onda =
          Math.sin(u * 14 + t * 3 + n) * amplitude +
          Math.sin(u * 31 - t * 5 + n * 2) * amplitude * 0.55;
        if (i === 0) ctx.moveTo(px, base + onda);
        else ctx.lineTo(px, base + onda);
      }
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // Os redemoinhos que sobram quando o espaçamento erra.
    if (desordem > 0.2) {
      const quantos = Math.round(desordem * 7);
      for (let i = 0; i < quantos; i++) {
        const fase = (t * 0.35 + i / quantos) % 1;
        const px = x0 + fase * (x1 - x0);
        const py = yPele - A * 0.06 - Math.sin(i * 2.3) * A * 0.05;
        // Miúdo demais o redemoinho vira um rabisco: ele é a única prova
        // visível de que a turbulência está de volta.
        const raio = A * 0.042 * (0.6 + desordem);

        ctx.strokeStyle = cor.erro;
        ctx.globalAlpha = 0.25 + desordem * 0.45;
        ctx.lineWidth = 2.4;
        ctx.beginPath();
        for (let k = 0; k <= 30; k++) {
          const ang = (k / 30) * Math.PI * 3.2 + t * 4;
          const r = raio * (k / 30);
          const x = px + Math.cos(ang) * r;
          const y = py + Math.sin(ang) * r;
          if (k === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }

    // ── A pele, com os sulcos ─────────────────────────────────────────────
    ctx.fillStyle = PELE;
    ctx.fillRect(x0, yPele, x1 - x0, A * 0.11);

    // O espaçamento na tela acompanha o slider (1–100 µm) sem sumir nem estourar.
    const passo = limitar((espacamento / 100) * (x1 - x0) * 0.09, 4, (x1 - x0) * 0.1);
    const alturaSulco = A * 0.05;

    ctx.fillStyle = PELE_CLARA;
    for (let x = x0 + passo / 2; x < x1; x += passo) {
      const largura = Math.min(passo * 0.4, alturaSulco * 0.55);
      ctx.beginPath();
      ctx.moveTo(x - largura / 2, yPele + 1);
      ctx.lineTo(x, yPele - alturaSulco);
      ctx.lineTo(x + largura / 2, yPele + 1);
      ctx.closePath();
      ctx.fill();
    }

    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(x0, yPele + 1);
    ctx.lineTo(x1, yPele + 1);
    ctx.stroke();

    const miudo = limitar(A * 0.032, 8, 11);
    texto(ctx, 'pele do tubarão', L / 2, yPele + A * 0.055, miudo, {
      cor: cor.contraste,
      peso: 700,
    });

    // A medida de um sulco ao vizinho — acima das pontas, na água clara: em
    // cima da pele ela ficava branca sobre cinza-azulado, quase apagada.
    const a = x0 + passo * 1.5;
    const b = a + passo;
    const yMedida = yPele - alturaSulco - miudo * 0.8;
    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(a, yMedida + 5);
    ctx.lineTo(a, yMedida);
    ctx.lineTo(b, yMedida);
    ctx.lineTo(b, yMedida + 5);
    ctx.stroke();
    texto(ctx, `${Math.round(espacamento)} µm`, (a + b) / 2, yMedida - miudo * 0.8, miudo * 0.9, {
      cor: cor.texto,
      peso: 700,
    });

    // ── O medidor de turbulência ──────────────────────────────────────────
    const yBarra = A * 0.88;
    const alturaBarra = limitar(A * 0.04, 7, 12);
    retangulo(ctx, x0, yBarra, x1 - x0, alturaBarra, alturaBarra / 2, cor.palha, cor.trilho, 1);
    retangulo(
      ctx,
      x0,
      yBarra,
      ((x1 - x0) * turbulencia) / 100,
      alturaBarra,
      alturaBarra / 2,
      ok ? cor.verde : turbulencia > 50 ? cor.erro : cor.ouro,
    );
    texto(ctx, `turbulência ${Math.round(turbulencia)}%`, L / 2, yBarra - miudo * 1.3, miudo, {
      cor: ok ? cor.verde : cor.fraco,
      peso: 700,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Fluxo colado: a água escorre sem atrito ✔',
      'Ajuste o espaçamento até a água passar lisa.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default fluxo;
